import { discoverModels, type CursorModelFallbackIssue } from "./model-discovery.js";
import { registerCursorFastControls } from "./cursor-state.js";
import { registerCursorNativeToolDisplay } from "./cursor-native-tool-display.js";
import { streamCursor, cursorCallbackOwners } from "./cursor-provider.js";

export default async function (pi: ExtensionAPI) {
	pi.registerCallbackOwnership?.(() => {
		const owners = cursorCallbackOwners();
		return { kind: owners.length ? "active" : "none", revision: JSON.stringify(owners), owners };
	});
	registerCursorFastControls(pi);
	registerCursorNativeToolDisplay(pi);
	let fallbackIssue: CursorModelFallbackIssue | undefined;
